#include <bits/stdc++.h>
using namespace std;

const long long MOD_A = 1000000007;
const long long MOD_B = 998244353;
const int MAX_DEPTH = 7;
const long long MULTIPLIER = 1000000;

long long limit, current_order;
int total_answer;
int partial_sums[MAX_DEPTH];
vector<int> digits_vectors[MAX_DEPTH];

void generate_sequences(int start, int depth) {
    current_order++;
    digits_vectors[depth].push_back(((current_order - start) % MOD_B + MOD_B) % MOD_B);
    partial_sums[depth] = (partial_sums[depth] + digits_vectors[depth].back()) % MOD_A;
    if (depth == 6) return;
    for (int digit = 0; digit <= 9; digit++) {
        generate_sequences(start * 10 + digit, depth + 1);
    }
}

void process_number(long long x) {
    if (x > limit) return;
    if (x * MULTIPLIER + MULTIPLIER - 1 <= limit && x * MULTIPLIER * 10 > limit) {
        long long saved_order = current_order;
        for (int depth = 0, factor = 1; depth <= 6; depth++, factor *= 10) {
            int size = (int)digits_vectors[depth].size();
            int diff = (int)(((saved_order - x * factor) % MOD_B + MOD_B) % MOD_B);
            int position = (int)(lower_bound(digits_vectors[depth].begin(), digits_vectors[depth].end(), (int)(MOD_B - diff)) - digits_vectors[depth].begin());
            total_answer = (total_answer + 1LL * diff * size + partial_sums[depth]) % MOD_A;
            total_answer = (total_answer - 1LL * MOD_B * (size - position) % MOD_A + MOD_A) % MOD_A;
            current_order += size;
        }
        return;
    }
    current_order++;
    total_answer = (total_answer + ((current_order - x) % MOD_B + MOD_B) % MOD_B) % MOD_A;
    for (int digit = 0; digit <= 9; digit++) {
        process_number(x * 10 + digit);
    }
}

int main() {
    cin >> limit;
    current_order = 0;
    generate_sequences(0, 0);
    for (int i = 0; i <= 6; i++) {
        sort(digits_vectors[i].begin(), digits_vectors[i].end());
    }
    current_order = 0;
    for (int i = 1; i <= 9; i++) {
        process_number(i);
    }
    cout << total_answer << "\n";
    return 0;
}
